import {publicProject} from '../work/projects.js';
import {createIssue,getIssue,publicLabel} from '../work/issues.js';
import {createComment,getComment} from '../work/comments.js';
import {createRelation,publicRelation,relationRow} from '../work/relations.js';
import {orderIssues,importPlan} from './transfer-validation.js';
function mapMentionIds(body,userMap) {
  return body.replace(/(@\[[^\]]+\]\(user:)([^\s)]+)(\))/g,(match,prefix,id,suffix)=>userMap.has(id)?prefix+userMap.get(id)+suffix:match)
    .replace(/@\{([^}\s]+)\}/g,(match,id)=>userMap.has(id)?'@{'+userMap.get(id)+'}':match);
}
function importedEvent(ctx,event) {
  if(event.entityType==='issue')return {...event,after:getIssue(ctx,event.entityId)};
  if(event.entityType==='comment'){
    const comment=getComment(ctx,event.entityId),issue=getIssue(ctx,comment.issueId);
    return {...event,issueId:issue.id,mentionedUserIds:comment.mentionedUserIds,
      after:{...comment,issue,userIds:comment.mentionedUserIds}};
  }
  if(event.entityType==='relation')return {...event,after:publicRelation(ctx,relationRow(ctx,event.entityId))};
  if(event.entityType==='label')return {...event,after:publicLabel(ctx.db.prepare('SELECT * FROM labels WHERE id=?').get(event.entityId))};
  return event;
}
export function importProject(ctx,req,orgId,body) {
  const plan=importPlan(ctx,req,orgId,body);
  if(body.preview)return {preview:plan.summary};
  const {document,userMap,externalIssueMap}=plan;
  const events=[],maps={statuses:new Map(),labels:new Map(),issues:new Map(),comments:new Map(),relations:new Map()};
  const staged={...ctx,transaction:fn=>fn(),bus:{emit:event=>{events.push(event);return event;}}};
  const projectId=ctx.id(),time=ctx.now();
  const result=ctx.transaction(()=>{
    ctx.db.prepare('INSERT INTO projects(id,org_id,key,name,description,created_at,updated_at) VALUES (?,?,?,?,?,?,?)')
      .run(projectId,orgId,plan.project.key,plan.project.name,plan.project.description,time,time);
    document.statuses.forEach((status,position)=>{
      const id=ctx.id();maps.statuses.set(status.id,id);
      ctx.db.prepare('INSERT INTO project_statuses VALUES (?,?,?,?,?)').run(id,projectId,status.name,status.category,position);
    });
    events.push({actorId:req.user.id,orgId,projectId,entityType:'project',entityId:projectId,action:'imported',before:null,time});
    for(const label of document.labels){
      const id=ctx.id();maps.labels.set(label.id,id);
      ctx.db.prepare('INSERT INTO labels VALUES (?,?,?,?,?,?)').run(id,projectId,label.name,label.color,label.createdAt,label.updatedAt);
      events.push({actorId:req.user.id,orgId,projectId,entityType:'label',entityId:id,action:'created',before:null,time});
    }
    for(const source of orderIssues(document.issues)) {
      const issue=createIssue(staged,req,projectId,{title:source.title,description:mapMentionIds(source.description,userMap),
        statusId:maps.statuses.get(source.statusId),priority:source.priority,
        assigneeId:source.assigneeId?userMap.get(source.assigneeId):null,estimate:source.estimate,dueDate:source.dueDate,
        parentId:source.parentId?maps.issues.get(source.parentId):null,labelIds:source.labelIds.map(id=>maps.labels.get(id))});
      maps.issues.set(source.id,issue.id);
      ctx.db.prepare('UPDATE issues SET created_by=?,rank=?,created_at=?,updated_at=? WHERE id=?')
        .run(userMap.get(source.createdBy),source.rank,source.createdAt,source.updatedAt,issue.id);
    }
    const maximum=document.issues.reduce((value,issue)=>Math.max(value,issue.number),0);
    document.issues.forEach((source,index)=>ctx.db.prepare('UPDATE issues SET number=? WHERE id=?').run(maximum+document.issues.length+index+1,maps.issues.get(source.id)));
    for(const source of document.issues)ctx.db.prepare('UPDATE issues SET number=? WHERE id=?').run(source.number,maps.issues.get(source.id));
    ctx.db.prepare('UPDATE projects SET next_issue_number=? WHERE id=?').run(maximum+1,projectId);
    for(const source of document.comments) {
      const comment=createComment(staged,req,maps.issues.get(source.issueId),{body:mapMentionIds(source.body,userMap)});
      maps.comments.set(source.id,comment.id);
      ctx.db.prepare('UPDATE comments SET author_id=?,created_at=?,updated_at=? WHERE id=?')
        .run(userMap.get(source.authorId),source.createdAt,source.updatedAt,comment.id);
    }
    const endpoint=id=>maps.issues.get(id)??externalIssueMap.get(id);
    for(const source of document.relations) {
      const relation=createRelation(staged,req,endpoint(source.sourceIssueId),{targetIssueId:endpoint(source.targetIssueId),kind:source.kind});
      maps.relations.set(source.id,relation.id);
      ctx.db.prepare('UPDATE issue_relations SET created_by=?,created_at=? WHERE id=?').run(userMap.get(source.createdBy),source.createdAt,relation.id);
    }
    const project=publicProject(ctx.db,ctx.db.prepare('SELECT * FROM projects WHERE id=?').get(projectId));
    events[0]={...events[0],after:project};
    return {project,counts:plan.summary.counts,mappings:{project:{from:body.document.project.id,to:projectId},
      ...Object.fromEntries(Object.entries(maps).map(([key,map])=>[key,Object.fromEntries(map)])),
      users:Object.fromEntries(userMap),externalIssues:Object.fromEntries(externalIssueMap)}};
  });
  for(const event of events)ctx.bus.emit(importedEvent(ctx,event));
  return result;
}

import {sendExport} from './transfer-export.js';
import {importProject} from './transfer-import.js';
export function registerTransferRoutes(ctx) {
  ctx.app.get('/api/v1/projects/:projectId/export',ctx.requireAuth,ctx.asyncRoute((req,res)=>sendExport(ctx,req,res)));
  ctx.app.post('/api/v1/orgs/:orgId/import',ctx.requireAuth,(req,res)=>{
    const result=importProject(ctx,req,req.params.orgId,req.body);
    res.status(req.body.preview?200:201).json(result);
  });
}
